# Simple simulation of Web Mining using TF-IDF for Content Mining
from sklearn.feature_extraction.text import TfidfVectorizer

# Simulated web pages retrieved by a crawler
web_pages = [
    "Artificial Intelligence and Machine Learning trends in 2026",
    "Introduction to Web Mining and Data Science concepts",
    "Advanced Machine Learning algorithms for web search"
];

# Initialize TF-IDF vectorizer
vectorizer = TfidfVectorizer(stop_words='english');

# Fit and transform the documents to find important keywords
tfidf_matrix = vectorizer.fit_transform(web_pages);

# Print feature names (extracted terms)
print("Extracted Vocabulary:", vectorizer.get_feature_names_out());
# Important: Higher TF-IDF score means the term is more representative of that page.

