# Simulation of a polite web crawler queue and duplicate URL detection subtask
from urllib.parse import urlparse

visited_urls = set();
url_queue = ["https://example.com/page1", "https://example.com/page2", "https://example.com/page1"];

def polite_crawler_step(queue):
    while queue:
        url = queue.pop(0);
        parsed = urlparse(url);
        normalized_url = f"{parsed.scheme}://{parsed.netloc}{parsed.path}";

        if normalized_url not in visited_urls:
            visited_urls.add(normalized_url);
            print(f"Crawling new URL: {normalized_url}");
        else:
            print(f"Skipping duplicate/visited URL: {normalized_url}");

polite_crawler_step(url_queue);
# Important: Deduplication prevents infinite loops in web crawlers.

