import re
def extract_links(html):
    return re.findall(r'<a[^>]*href="([^"]*)"[^>]*>(.*?)</a>', html, re.IGNORECASE)

def compute_tfidf(corpus):
    from collections import Counter
    import math
    N = len(corpus)
    idf = {}
    tf_list = []
    unique_terms = set(word for doc in corpus for word in doc.lower().split())
    for term in unique_terms:
        doc_count = sum(1 for doc in corpus if term in doc.lower().split())
        idf[term] = math.log(N / (1 + doc_count))
    for doc in corpus:
        words = doc.lower().split()
        counts = Counter(words)
        tf = {word: count/len(words) for word, count in counts.items()}
        tf_list.append({term: tf.get(term, 0) * idf[term] for term in unique_terms})
    return tf_list

