from collections import defaultdict

# Simplified Inverted Index Construction in Python 3.13+
class InvertedIndex:
    def __init__(self):
        self.index = defaultdict(list)

    def add_document(self, doc_id, text):
        tokens = text.lower().split()
        for position, token in enumerate(tokens):
            if doc_id not in [item[0] for item in self.index[token]]:
                self.index[token].append((doc_id, [position]))
            else:
                for idx, (d_id, pos_list) in enumerate(self.index[token]):
                    if d_id == doc_id:
                        pos_list.append(position)

    def search(self, term):
        return self.index.get(term.lower(), [])

# Test index
